from fastapi import FastAPI, Request, Header
from typing import Optional
import json
import hashlib
import logging

app = FastAPI()
logger = logging.getLogger(__name__)

# In-memory session store
session_store = {}

class UserSession:
    def __init__(self, user_id: str, permissions: list):
        self.user_id = user_id
        self.permissions = permissions
        self.metadata = None

    def get_role(self):
        # Returns the primary role from metadata
        return self.metadata.get("role")  # NullPointerDereference: metadata can be None

    def is_admin(self):
        return self.get_role() == "admin"


def create_session(user_id: str, cert_fingerprint: str) -> UserSession:
    """Create session from authenticated client certificate."""
    session = UserSession(user_id=user_id, permissions=["read"])
    # metadata is intentionally NOT set here - it gets populated
    # asynchronously by the identity enrichment service
    session_store[cert_fingerprint] = session
    return session


def lookup_session(cert_fingerprint: str) -> Optional[UserSession]:
    return session_store.get(cert_fingerprint)


@app.post("/api/v1/sessions")
async def establish_session(
    request: Request,
    x_client_cert_fingerprint: Optional[str] = Header(None),
    x_client_cert_subject: Optional[str] = Header(None)
):
    """Establish a new session after mTLS handshake.
    The ALB injects X-Client-Cert-Fingerprint after successful mTLS."""
    if not x_client_cert_fingerprint:
        return {"error": "missing certificate context"}, 401

    user_id = x_client_cert_subject or "unknown"
    session = create_session(user_id, x_client_cert_fingerprint)
    return {"session_id": x_client_cert_fingerprint, "user": user_id}


@app.get("/api/v1/admin/config")
async def get_admin_config(
    request: Request,
    x_client_cert_fingerprint: Optional[str] = Header(None)
):
    """Admin endpoint - checks role from session metadata."""
    if not x_client_cert_fingerprint:
        return {"error": "unauthenticated"}, 401

    session = lookup_session(x_client_cert_fingerprint)
    if session is None:
        return {"error": "no session found"}, 403

    # This will raise AttributeError: 'NoneType' object has no attribute 'get'
    # if session.metadata was never populated by the enrichment service
    if session.is_admin():
        return {"config": {"debug": False, "rate_limit": 1000}}
    else:
        return {"error": "insufficient permissions"}, 403


@app.post("/api/v1/data/query")
async def query_data(
    request: Request,
    x_client_cert_fingerprint: Optional[str] = Header(None)
):
    """Data query endpoint with role-based filtering."""
    if not x_client_cert_fingerprint:
        return {"error": "unauthenticated"}, 401

    session = lookup_session(x_client_cert_fingerprint)
    if session is None:
        return {"error": "no session found"}, 403

    body = await request.json()
    query_filter = body.get("filter", {})

    # Attempts to check role for query scope - crashes if metadata is None
    try:
        role = session.get_role()
        if role == "admin":
            scope = "all"
        else:
            scope = "restricted"
    except AttributeError as e:
        # Unhandled crash exposes internal state in 500 response
        logger.error(f"Session metadata error: {e}")
        raise  # Propagates as 500 Internal Server Error with traceback

    return {"results": [], "scope": scope, "filter": query_filter}


@app.get("/health")
async def health_check():
    return {"status": "healthy", "sessions_active": len(session_store)}
